mapper.select:
select cast(u.user_id as char) as option_value, concat(u.nick_name, ' (', u.user_name, ')') as option_label, 'user' as option_type from sys_user u where u.status = '0' and u.del_flag = '0'
and (u.nick_name like concat('%', #{keyword}, '%') or u.user_name like concat('%', #{keyword}, '%'))
order by u.user_name, u.user_id limit #{offset}, #{pageSize}

choose.when:
select count(*) from sys_role r where r.status = '0' and r.del_flag = '0' and exists ( select 1 from sys_user_role member_ur inner join sys_user u on u.user_id = member_ur.user_id where member_ur.role_id = r.role_id and u.status = '0' and u.del_flag = '0'
)
and (r.role_name like concat('%', #{keyword}, '%') or r.role_key like concat('%', #{keyword}, '%'))

choose.otherwise:
select count(*) from sys_dept d where d.status = '0' and d.del_flag = '0' and exists ( select 1 from sys_user u where u.dept_id = d.dept_id and u.status = '0' and u.del_flag = '0'
)
and d.dept_name like concat('%', #{keyword}, '%')

choose.when:
select cast(u.user_id as char) as option_value, concat(u.nick_name, ' (', u.user_name, ')') as option_label, 'user' as option_type, (u.status = '0' and u.del_flag = '0') as available from sys_user u where u.user_id in
#{id}
order by u.user_id

select concat('ROLE', r.role_id) as option_value, concat('角色: ', r.role_name) as option_label, 'role' as option_type, (r.status = '0' and r.del_flag = '0') as available from sys_role r where r.role_id in
#{id}
order by r.role_id

choose.otherwise:
select concat('DEPT', d.dept_id) as option_value, concat('部门: ', d.dept_name) as option_label, 'dept' as option_type, (d.status = '0' and d.del_flag = '0') as available from sys_dept d where d.dept_id in
#{id}
order by d.dept_id

